59: export function baselineFromSamples(
60:   samples: readonly PulseSample[],
61:   startUs: number,
62:   floor = CONFIDENCE_FLOOR,
63: ): Pick<SessionMeta, 'baselineBpm' | 'baselineWindow'> | undefined {
64:   const toUs = startUs + BASELINE_WINDOW_US;
65:   const values = samples
66:     .filter((sample) => sample.tUs >= startUs && sample.tUs < toUs && isUsableSample(sample, floor))
67:     .map((sample) => sample.bpm);
