81:   if (stopUs < startUs) throw new Error('The session clock moved backwards.');
82:   const totalUs = stopUs - startUs;
83:   const ordered = samples
84:     .filter((sample) => sample.tUs >= startUs && sample.tUs <= stopUs)
85:     .sort((a, b) => a.tUs - b.tUs);
86:   let usableUs = 0;
87:   for (let index = 0; index < ordered.length; index += 1) {
88:     const sample = ordered[index];
89:     if (!isUsableSample(sample, floor)) continue;
90:     const nextUs = index + 1 < ordered.length ? ordered[index + 1].tUs : stopUs;
91:     const gap = nextUs - sample.tUs;
92:     if (gap <= 0) continue;
93:     usableUs += Math.min(gap, SAMPLE_HOLD_US);
94:   }
95:   if (usableUs > totalUs) usableUs = totalUs;
96:   const pct = totalUs === 0 ? 0 : (usableUs / totalUs) * 100;
