168: export async function stopSession(
169:   root: string,
170:   stopAnchor: SessionAnchor,
171:   reason: SessionStopReason,
172: ): Promise<SessionMeta> {
173:   const key = path.resolve(root);
174:   const current = active.get(key);
175:   if (!current) throw new Error('No session is running.');
176:   if (current.state === 'starting') {
