188: function beginStop(
189:   root: string,
190:   key: string,
191:   current: ActiveSession,
192:   sessionId: string,
193:   stopAnchor: SessionAnchor,
194:   reason: SessionStopReason,
195: ): Promise<SessionMeta> {
196:   if (current.finishStop) return current.finishStop;
197:   const run = (async () => {
