229:       const meta = await readMeta(root, id);
230:       if (meta.stopReason) continue;
231:       const samples = await readSamples(root, id);
232:       const lastUs = samples.reduce((max, sample) => Math.max(max, sample.tUs), meta.startAnchor.monoUs);
233:       const stopAnchor = {
234:         monoUs: lastUs,
235:         epochMs: meta.startAnchor.epochMs + Math.round((lastUs - meta.startAnchor.monoUs) / 1000),
