259:   const coverage = coverageFromSamples(samples, meta.startAnchor.monoUs, stopAnchor.monoUs);
260:   await saveMeta(root, {
261:     ...meta,
262:     ...baseline,
263:     stopAnchor,
264:     stopReason: reason,
265:     coverage,
266:   });
267:   return readMeta(root, meta.id);
268: }
