275:   anchor: SessionAnchor,
276:   timeControl: string,
277:   limitScheduler: SessionLimitScheduler,
278: ): ActiveSession {
279:   let resolveStopped: (meta: SessionMeta) => void = () => undefined;
280:   let rejectStopped: (error: unknown) => void = () => undefined;
281:   const stopped = new Promise<SessionMeta>((resolve, reject) => {
282:     resolveStopped = resolve;
283:     rejectStopped = reject;
284:   });
285:   stopped.catch(() => undefined);
286:   return {
287:     anchor,
288:     timeControl,
289:     state: 'starting',
290:     ingest: Promise.resolve(),
291:     stopped,
292:     resolveStopped,
293:     rejectStopped,
294:     limitScheduler,
295:   };
296: }
297: 
298: function armLimitTimer(key: string, current: ActiveSession, onLimit: (() => void) | undefined): void {
299:   current.limitTimer = current.limitScheduler.set(() => {
300:     current.limitTimer = undefined;
301:     if (active.get(key) !== current || current.state !== 'running') return;
302:     try {
303:       onLimit?.();
304:     } catch {
305:       // The next explicit stop still closes the session; a timer callback must not crash main.
306:     }
307:   }, MAX_SESSION_US / 1000);
308: }
