254:           const when = moveTimes.find((time) => time.gameIndex === aligned.game.index && time.moveIndex === rest);
255:           const rawThink = thinks[rest] ?? null;
256:           metrics.push({
257:             cpl: null,
258:             accuracy: null,
259:             blunder: false,
260:             band: null,
261:             includeInStats: true,
262:           });
263:           timelineMoves.push({
264:             gameIndex: aligned.game.index,
265:             moveIndex: rest,
266:             san: sans[rest] ?? '',
267:             tUs: when?.tUs ?? null,
268:             cpl: null,
269:             thinkSec: rawThink !== null && rawThink >= 0 ? rawThink : null,
270:             blunder: false,
271:             band: null,
272:           });
273:         }
274:         break;
275:       }
276:       const when = moveTimes.find((time) => time.gameIndex === aligned.game.index && time.moveIndex === moveIndex);
277:       const before = await evaluate(position.fenBefore);
278:       const after = await evaluate(position.fenAfter);
