299: export function bandAt(samples: readonly PulseSample[], tUs: number, baseline: number): ReturnType<typeof bandFor> {
300:   let latest: PulseSample | undefined;
301:   for (const sample of samples) {
302:     if (sample.tUs <= tUs && (!latest || sample.tUs >= latest.tUs)) latest = sample;
303:   }
304:   if (!latest || !isUsableSample(latest, CONFIDENCE_FLOOR)) return null;
305:   if (tUs > latest.tUs + SAMPLE_HOLD_US) return null;
306:   return bandFor(latest.bpm, baseline);
307: }
