309: export function elevatedClaim(
310:   samples: readonly PulseSample[],
311:   startUs: number,
312:   stopUs: number,
313:   baseline: number,
314:   blunderTimes: readonly (number | null)[],
315: ): { elevatedMinutes: number; deltaBpm: number } | undefined {
316:   if (blunderTimes.length === 0 || blunderTimes.some((time) => time === null)) return undefined;
317:   const periods = elevatedPeriods(samples, startUs, stopUs, baseline);
318:   const hit = new Set<number>();
319:   for (const time of blunderTimes) {
320:     const index = periods.findIndex((period) => (time ?? -1) >= period.fromUs && (time ?? -1) <= period.toUs);
321:     if (index < 0) return undefined;
322:     hit.add(index);
323:     if (hit.size > 1) return undefined;
324:   }
325:   const period = periods[[...hit][0] ?? -1];
326:   if (!period) return undefined;
327:   return {
328:     elevatedMinutes: (period.toUs - period.fromUs) / 60_000_000,
329:     deltaBpm: Math.round(period.deltaBpm),
330:   };
331: }
