333: function elevatedPeriods(
334:   samples: readonly PulseSample[],
335:   startUs: number,
336:   stopUs: number,
337:   baseline: number,
338: ): { fromUs: number; toUs: number; deltaBpm: number }[] {
339:   const ordered = samples
340:     .filter((sample) => sample.tUs >= startUs && sample.tUs <= stopUs)
341:     .sort((left, right) => left.tUs - right.tUs);
342:   const periods: { fromUs: number; toUs: number; deltaBpm: number }[] = [];
343:   let current: { fromUs: number; toUs: number; deltaBpm: number } | undefined;
344:   for (let index = 0; index < ordered.length; index += 1) {
345:     const sample = ordered[index];
346:     if (!sample || !isUsableSample(sample, CONFIDENCE_FLOOR) || bandFor(sample.bpm, baseline) !== 'elevated') {
347:       current = undefined;
348:       continue;
349:     }
350:     const nextUs = index + 1 < ordered.length ? ordered[index + 1]?.tUs ?? stopUs : stopUs;
351:     const gap = nextUs - sample.tUs;
352:     const end = sample.tUs + (gap > 0 ? Math.min(gap, SAMPLE_HOLD_US) : 0);
353:     if (!current) {
354:       current = { fromUs: sample.tUs, toUs: end, deltaBpm: sample.bpm - baseline };
355:       periods.push(current);
356:     } else {
357:       current.toUs = end;
358:       current.deltaBpm = Math.max(current.deltaBpm, sample.bpm - baseline);
359:     }
360:     const next = ordered[index + 1];
361:     const continues =
362:       next !== undefined &&
363:       gap > 0 &&
364:       gap <= SAMPLE_HOLD_US &&
365:       isUsableSample(next, CONFIDENCE_FLOOR) &&
366:       bandFor(next.bpm, baseline) === 'elevated';
367:     if (!continues) current = undefined;
368:   }
369:   return periods;
370: }
371: 
372: function gapClause(gaps: readonly { afterIndex: number; beforeIndex: number; durationUs: number }[]): string | undefined {
373:   const gap = gaps.reduce<(typeof gaps)[number] | undefined>((best, current) => {
374:     if (!best || current.durationUs > best.durationUs) return current;
375:     return best;
376:   }, undefined);
377:   if (!gap) return undefined;
378:   const minutes = Math.round(gap.durationUs / 60_000_000);
379:   const seconds = Math.max(1, Math.round(gap.durationUs / 1_000_000));
380:   const waited =
381:     minutes >= 1
382:       ? `${minutes} ${minutes === 1 ? 'minute' : 'minutes'}`
383:       : `${seconds} ${seconds === 1 ? 'second' : 'seconds'}`;
384:   return `Between games ${gap.afterIndex + 1} and ${gap.beforeIndex + 1} you waited ${waited}.`;
385: }
