379:   const seconds = Math.max(1, Math.round(gap.durationUs / 1_000_000));
380:   const waited =
381:     minutes >= 1
382:       ? `${minutes} ${minutes === 1 ? 'minute' : 'minutes'}`
383:       : `${seconds} ${seconds === 1 ? 'second' : 'seconds'}`;
384:   return `Between games ${gap.afterIndex + 1} and ${gap.beforeIndex + 1} you waited ${waited}.`;
